public static void sort(int[] data){
  int m;
  int index;
  int temp;
  int count = 0;

  for(int i = 0; i < data.length; i++){
    index = i; // line 1
    m = 0; // line 2

    for(int j = i; j < data.length; j++){
      count++;

      if( data[j] < m){
        index = j; // line 3
        m = data[j]; // line 4
      }
    }

    temp = data[i];
    data[i] = data[index];
    data[index] = temp;
  }
  // line 5
}

public static void show(){
  int[] d2 = {14, 1, -1, 10, 5};
  sort(d2);

  for(int i = 0; i < d2.length; i++)
    System.out.print( d2[i] + " ");
}

