  public Game(int[][] init){
    int r = init.length;
    int c = init[0].length;
    w = new int[r][c];
    for(int i = 0; i < r; i++)
      for(int j = 0; j < c; j++)
        w[i][j] = init[i][j];
  }

  public void next(){
    int[][] gen1 = new int[w.length][w[0].length];
    int n;
    for(int r = 0; r< w.length; r++)
      for(int c = 0; c < w[0].length; c++){
        n = numNeigh(r, c);
        if( w[r][c] == 1 && (n == 2 || n == 3) )
          gen1[r][c] = 1;
        else if( n == 3 )
          gen1[r][c] = 1;
      }
    w = gen1;
  }

  private int numNeigh(int row, int col){
    int total = 0;
    for(int r = row -1; r <= row + 1; r++)
      for(int c = col - 1; c <= col + 1; c++)
        if(inbounds(r,c,w) && w[r][c] == 1)
          total++;
    <*1>
