  }

  public String toString(){
    String result = "";
    for(int r = 0; r < w.length; r++){
      for(int c = 0; c < w[0].length; c++)
        result += ( w[r][c] == 1 ) ? "*" : ".";
      result += "\n";
    }
    return result;
  }

}

